export type PapelCor = 'fundo' | 'grama' | 'giz' | 'branco' | 'tinta' | 'contorno' | 'sup' | 'neutro' | 'verde' | 'azul' | 'laranja' | 'ouro' | 'prata' | 'bronze' | 'amarelo' | 'vidro' | 'sombra' | 'brilho';
export type ArteId = 'apito' | 'banco_vazio' | 'bola_na_trave' | 'campo' | 'chuteiras' | 'coletes_varal' | 'cones' | 'ingressos' | 'lupa' | 'mapa_campo' | 'medalha' | 'placar_zerado' | 'podio' | 'prancheta_vazia' | 'sorteio' | 'vaquinha';
