export type AnimacaoArte = 'rolar' | 'cair' | 'piscar' | 'quicar';

/** Caminho: d, preenchimento (f), traço (s), largura (w), ponta (lc), junção (lj), tracejado (da), opacidade (o). */
export interface CaminhoArte { d: string; f?: PapelCor; s?: PapelCor; w?: number; lc?: 'round' | 'square'; lj?: 'round' | 'bevel'; da?: number[]; o?: number }
/** Grupo: filhos (g), matriz [a b c d e f] (m), opacidade (o), animação (a). */
export interface GrupoArte { g: NoArte[]; m?: number[]; o?: number; a?: AnimacaoArte }
export type NoArte = CaminhoArte | GrupoArte;
export interface Arte { largura: number; altura: number; nos: NoArte[] }
export interface EstadoAnimacao { dx?: number; dy?: number; graus?: number; escala?: number; alfa?: number }
export interface EspecAnimacao { duracaoMs: number; alternar: boolean; curva: [number, number, number, number]; quadros: [number, EstadoAnimacao][] }

